=== MLX activations.rs ===
//! MLX-backed unary activations (Saga 14 step 002).
//!
//! Forward-pass only. Each op is a 1:1 elementwise map, so shape
//! and labels pass through unchanged. Backward passes (gradcheck
//! parity) land in step 006.

use mlpl_array::DenseArray;
use mlx_rs::Array as MlxArray;

use crate::common::{dense_to_mlx, mlx_to_dense_data};

/// `exp(x)` elementwise. Infallible (shape and labels are preserved
/// from `a`, so the MLX kernel only sees pre-validated input).
#[must_use]
pub fn exp(a: &DenseArray) -> DenseArray {
    apply_unary(a, |x| x.exp().expect("mlx exp on validated shape"))
}

/// Natural log `ln(x)` elementwise.
#[must_use]
pub fn log(a: &DenseArray) -> DenseArray {
    apply_unary(a, |x| x.log().expect("mlx log on validated shape"))
}

/// Hyperbolic tangent `tanh(x)` elementwise.
#[must_use]
pub fn tanh(a: &DenseArray) -> DenseArray {
    apply_unary(a, |x| {
        mlx_rs::ops::tanh(x).expect("mlx tanh on validated shape")
    })
}

/// Logistic sigmoid `1 / (1 + exp(-x))` elementwise.
#[must_use]
pub fn sigmoid(a: &DenseArray) -> DenseArray {
    apply_unary(a, |x| {
        mlx_rs::ops::sigmoid(x).expect("mlx sigmoid on validated shape")
    })
}

/// Rectified linear unit `max(x, 0)` elementwise.
#[must_use]
pub fn relu(a: &DenseArray) -> DenseArray {
    apply_unary(a, |x| {
        mlx_rs::nn::relu(x).expect("mlx relu on validated shape")
    })
}

/// Shared dispatch for the unary activations: cast to MLX fp32,
/// run `op`, cast back to f64, and re-attach shape and labels.
/// Output shape is identical to input, so no shape validation is
/// possible (or needed) -- DenseArray::new + with_labels cannot
/// fail on data the input already carried.
fn apply_unary(a: &DenseArray, op: impl FnOnce(&MlxArray) -> MlxArray) -> DenseArray {
    let mlx = dense_to_mlx(a.data(), a.shape().dims());
    let result = op(&mlx);
    let data = mlx_to_dense_data(result);
    let array =
        DenseArray::new(a.shape().clone(), data).expect("output element count matches input");
    match a.labels() {
        Some(lbls) => array
            .with_labels(lbls.to_vec())
            .expect("labels already validated on input"),
        None => array,
    }
}
=== MLX shapes.rs ===
//! MLX-backed shape primitives (Saga 14 step 002).
//!
//! Shape-metadata ops -- `reshape` and `transpose` -- dispatch
//! through MLX's own shape kernels so the Saga 14 promise "every
//! primitive runs on MLX" holds end-to-end. Values travel through
//! the fp32 round trip in `common::dense_to_mlx` + `mlx_to_dense_data`
//! like every other op, so parity tests share the same tolerance
//! budget.
//!
//! Label propagation mirrors `mlpl-array`:
//! - `reshape` drops labels (a reshaped array no longer carries
//!   the old per-axis identity).
//! - `transpose` reverses the label list alongside the axes.

use mlpl_array::{ArrayError, DenseArray, Shape};
use mlpl_array_ops_shape::prelude::*;

use crate::common::{dense_to_mlx, finalize, mlx_to_dense_data};

/// `reshape(a, dims)` -- reinterpret `a` with new dims. Element
/// count must match or `ArrayError::ShapeMismatch` is returned.
/// Labels drop, matching the CPU path.
pub fn reshape(a: &DenseArray, dims: &[usize]) -> Result<DenseArray, ArrayError> {
    let source = a.elem_count();
    let target: usize = dims.iter().product();
    if source != target {
        return Err(ArrayError::ShapeMismatch { source, target });
    }
    let mlx = dense_to_mlx(a.data(), a.shape().dims());
    let new_shape_i32: Vec<i32> = dims.iter().map(|&d| d as i32).collect();
    let reshaped = mlx
        .reshape(&new_shape_i32)
        .expect("mlx reshape on validated element count");
    finalize(Shape::new(dims.to_vec()), mlx_to_dense_data(reshaped), None)
}

/// `transpose(a)` -- reverse axis order and reorder data to
/// row-major. Labels reverse alongside axes. Infallible, matching
/// `mlpl_rt::transpose`.
///
/// Implementation note: MLX 0.25.3 exposes `transpose` as a lazy
/// view with permuted strides, and `as_slice` on a view still
/// returns the underlying row-major buffer -- mlx-rs does not
/// surface the C `mlx_contiguous` helper that would force a
/// rematerialized copy. We therefore delegate to the CPU path,
/// which is a fixed-size stride walk and cheap at Saga 14 sizes.
/// Once `device("mlx") { }` chains fuse transpose with downstream
/// ops (Phase 2, step 005), the intermediate view never lands in
/// a flat buffer and this fallback disappears.
#[must_use]
pub fn transpose(a: &DenseArray) -> DenseArray {
    a.transpose()
}
=== MLX reductions.rs ===
//! MLX-backed reductions, normalisation, and loss primitives
//! (Saga 14 step 003).
//!
//! Signatures mirror `mlpl-rt::reductions` so compiled MLPL code
//! can swap runtimes without source changes:
//!
//! - `reduce_mul` / `mean` / `argmax` take `Option<usize>` axis
//!   (None = flat reduction over the whole array).
//! - `softmax` / `log_softmax` take `usize` axis.
//! - `cross_entropy(logits, targets)` is a fused log-softmax + NLL
//!   that returns an unlabeled scalar mean.
//!
//! Validation (axis bounds, target integrality, target range) lives
//! on the Rust side so MLX sees only legal inputs. Numerical work
//! routes through MLX's own kernels (`prod`, `mean`, `argmax`,
//! `softmax_axis`, `log_softmax`, `logsumexp_axis`); the fp32
//! GPU/Accelerate path means parity tests use a documented
//! tolerance rather than bit-for-bit equality. Label propagation
//! follows Saga 11.5: reductions drop the reduced axis label,
//! softmax/log_softmax preserve labels, cross_entropy returns
//! unlabeled.

use mlpl_array::{ArrayError, DenseArray, Shape};

use crate::common::{dense_to_mlx, finalize, mlx_to_dense_data};

/// Product reduction over `axis` (None = flat).
pub fn reduce_mul(a: &DenseArray, axis: Option<usize>) -> Result<DenseArray, ArrayError> {
    let mlx = dense_to_mlx(a.data(), a.shape().dims());
    if let Some(ax) = axis {
        let dims = a.shape().dims();
        if ax >= dims.len() {
            return Err(ArrayError::IndexOutOfBounds {
                axis: ax,
                index: ax,
                size: dims.len(),
            });
        }
        let reduced = mlx
            .prod_axis(ax as i32, false)
            .expect("mlx prod_axis on validated axis");
        let (out_dims, labels) = drop_axis(a, ax);
        return finalize(Shape::new(out_dims), mlx_to_dense_data(reduced), labels);
    }
    let reduced = mlx.prod(false).expect("mlx prod on validated array");
    finalize(Shape::new(vec![]), mlx_to_dense_data(reduced), None)
}

/// Mean reduction over `axis` (None = flat).
pub fn mean(a: &DenseArray, axis: Option<usize>) -> Result<DenseArray, ArrayError> {
    let mlx = dense_to_mlx(a.data(), a.shape().dims());
    if let Some(ax) = axis {
        let dims = a.shape().dims();
        if ax >= dims.len() {
            return Err(ArrayError::IndexOutOfBounds {
                axis: ax,
                index: ax,
                size: dims.len(),
            });
        }
        let reduced = mlx
            .mean_axis(ax as i32, false)
            .expect("mlx mean_axis on validated axis");
        let (out_dims, labels) = drop_axis(a, ax);
        return finalize(Shape::new(out_dims), mlx_to_dense_data(reduced), labels);
    }
    let reduced = mlx.mean(false).expect("mlx mean on validated array");
    finalize(Shape::new(vec![]), mlx_to_dense_data(reduced), None)
}

/// Index of the maximum value over `axis` (None = flat). The
/// MLX-side argmax returns an unsigned integer array; we cast it
/// to f32 so the f64 round trip in `mlx_to_dense_data` agrees with
/// the CPU path's `f64` index representation.
pub fn argmax(a: &DenseArray, axis: Option<usize>) -> Result<DenseArray, ArrayError> {
    if a.elem_count() == 0 && axis.is_none() {
        return Err(ArrayError::EmptyArray);
