        if t < 0.0 || t.fract() != 0.0 {
            return Err(ArrayError::IndexOutOfBounds {
                axis: 0,
                index: i,
                size: v,
            });
        }
        let ti = t as usize;
        if ti >= v {
            return Err(ArrayError::IndexOutOfBounds {
                axis: 0,
                index: ti,
                size: v,
            });
        }
        idx.push(ti);
    }
