use mlpl_array::{ArrayError, DenseArray, Shape};

/// Build a contiguous fp32 CUDA tensor from a `DenseArray`'s f64
/// buffer. The caller validates shape; this only handles the f64 ->
/// f32 cast and device placement.
///
/// # Panics
/// Panics if candle cannot allocate the tensor on the GPU for a
/// pre-validated element count.
#[must_use]
pub fn dense_to_cuda(data: &[f64], dims: &[usize]) -> Tensor {
    let data_f32: Vec<f32> = data.iter().map(|&x| x as f32).collect();
    Tensor::from_vec(data_f32, dims.to_vec(), cuda_device())
        .expect("cuda tensor from pre-validated shape")
}

/// Materialize a CUDA tensor and cast its flat contents back to f64.
///
/// # Panics
/// Panics if candle cannot copy the tensor to host memory.
#[must_use]
pub fn cuda_to_dense_data(t: &Tensor) -> Vec<f64> {
    let flat = t.flatten_all().expect("flatten cuda tensor");
    let out: Vec<f32> = flat.to_vec1::<f32>().expect("cuda tensor to host f32");
    out.iter().map(|&x| f64::from(x)).collect()
}

/// Wrap `data` in a `DenseArray` of `shape`, attaching `labels` if
/// present. Consolidates the new + with_labels dance every op does.
///
/// # Errors
/// Returns `ArrayError` if the data length does not match `shape`
/// or the labels are invalid for the shape.
pub fn finalize(
    shape: Shape,
    data: Vec<f64>,
    labels: Option<Vec<Option<String>>>,
) -> Result<DenseArray, ArrayError> {
    let array = DenseArray::new(shape, data)?;
    match labels {
        Some(lbls) => array.with_labels(lbls),
        None => Ok(array),
    }
}

/// Mirror of `mlpl-array`'s private `merge_labels`: scalars defer to
/// the non-scalar side; two labeled sides must agree.
pub(crate) fn merge_labels(
    a: &DenseArray,
    b: &DenseArray,
) -> Result<Option<Vec<Option<String>>>, ArrayError> {
    if a.rank() == 0 {
        return Ok(b.labels().map(<[Option<String>]>::to_vec));
    }
    if b.rank() == 0 {
        return Ok(a.labels().map(<[Option<String>]>::to_vec));
    }
    match (a.labels(), b.labels()) {
        (None, None) => Ok(None),
        (Some(l), None) | (None, Some(l)) => Ok(Some(l.to_vec())),
        (Some(la), Some(lb)) if la == lb => Ok(Some(la.to_vec())),
        (Some(la), Some(lb)) => Err(ArrayError::LabelMismatch {
            expected: la.to_vec(),
            actual: lb.to_vec(),
        }),
    }
}

/// Prep for a binary elementwise op: merge labels and resolve the
/// result shape (scalar broadcast or same-shape equality).
///
/// # Errors
/// `LabelMismatch` if labels disagree; `ShapeMismatch` if neither
/// operand is scalar and the shapes differ.
pub(crate) fn binary_prep(
    a: &DenseArray,
    b: &DenseArray,
) -> Result<(Shape, Option<Vec<Option<String>>>), ArrayError> {
    let labels = merge_labels(a, b)?;
    let shape = if a.rank() == 0 {
        b.shape().clone()
    } else if b.rank() == 0 || a.shape() == b.shape() {
        a.shape().clone()
    } else {
        return Err(ArrayError::ShapeMismatch {
            source: a.elem_count(),
            target: b.elem_count(),
        });
    };
    Ok((shape, labels))
}

