/// must match. Labels drop, matching the CPU path.
///
/// # Errors
/// `ShapeMismatch` if the element count differs from `dims`'s product.
pub fn reshape(a: &DenseArray, dims: &[usize]) -> Result<DenseArray, ArrayError> {
    let source = a.elem_count();
    let target: usize = dims.iter().product();
    if source != target {
        return Err(ArrayError::ShapeMismatch { source, target });
    }
    let t = dense_to_cuda(a.data(), a.shape().dims());
    let r = t
        .reshape(dims.to_vec())
        .expect("cuda reshape on validated count");
    finalize(Shape::new(dims.to_vec()), cuda_to_dense_data(&r), None)
}

/// `transpose(a)` -- reverse axis order, reorder data to row-major,
/// reverse labels. Delegates to the CPU stride walk (cheap at these
/// sizes); candle transpose is a strided view whose flat readback
/// would not match without an explicit contiguous copy.
#[must_use]
pub fn transpose(a: &DenseArray) -> DenseArray {
    a.transpose()
}

/// Mirror of `mlpl-array`'s private `matmul_labels`: contraction
/// labels must agree; survivors are `[a.labels[0], b.labels[1]]`.
fn matmul_labels(
    a: &DenseArray,
    b: &DenseArray,
) -> Result<Option<Vec<Option<String>>>, ArrayError> {
    if a.labels().is_none() && b.labels().is_none() {
        return Ok(None);
    }
    let default_b = vec![None; b.rank()];
    let al: &[Option<String>] = a.labels().unwrap_or(&[None, None][..]);
    let bl: &[Option<String>] = b.labels().unwrap_or(default_b.as_slice());
    if let (Some(sa), Some(sb)) = (&al[1], &bl[0])
        && sa != sb
    {
        return Err(ArrayError::LabelMismatch {
            expected: al.to_vec(),
            actual: bl.to_vec(),
        });
    }
    let mut result = vec![al[0].clone()];
    if b.rank() == 2 {
        result.push(bl[1].clone());
    }
    Ok(Some(result))
}

