//! CUDA-backed normalization + loss. `softmax`/`log_softmax` run on
//! the GPU (candle-nn ops, preserving shape and labels) and share one
//! body via the `norm!` macro. `cross_entropy` mirrors `mlpl-rt`: a
//! fused log-softmax + NLL over `[N, V]` logits returning an
//! unlabeled scalar mean, with targets validated up front.

use mlpl_array::{ArrayError, DenseArray};
use mlpl_cuda_rt::{cuda_to_dense_data, dense_to_cuda, finalize};

macro_rules! norm {
    ($name:ident, $doc:literal, $op:path) => {
        #[doc = $doc]
        ///
        /// # Errors
        /// `IndexOutOfBounds` if `axis` is out of range.
        ///
        /// # Panics
        /// Panics if the candle kernel fails on a validated axis.
        pub fn $name(a: &DenseArray, axis: usize) -> Result<DenseArray, ArrayError> {
            if axis >= a.rank() {
                return Err(ArrayError::IndexOutOfBounds {
                    axis,
                    index: axis,
                    size: a.rank(),
                });
            }
            let t = dense_to_cuda(a.data(), a.shape().dims());
            let r = $op(&t, axis).expect(concat!("cuda ", stringify!($name), " on axis"));
            let labels = a.labels().map(<[Option<String>]>::to_vec);
            finalize(a.shape().clone(), cuda_to_dense_data(&r), labels)
        }
    };
}

norm!(
    softmax,
    "`softmax(a, axis)` on the GPU; shape and labels match the input.",
    candle_nn::ops::softmax
);
norm!(
    log_softmax,
    "`log_softmax(a, axis)` on the GPU; shape and labels match input.",
    candle_nn::ops::log_softmax
);

/// `cross_entropy(logits, targets)`: fused log-softmax + NLL, scalar
/// mean. `logits` are `[N, V]` (or `[B, T, V]` flattened); `targets`
/// are `N` class indices. Per-row log-sum-exp runs on the GPU; the
/// gather + mean run on the CPU (matching `mlpl-rt`).
///
/// # Errors
/// `RankMismatch` if `logits` is not rank 2 or 3; `ShapeMismatch` if
/// the target count is not `N`; `IndexOutOfBounds` for a target that
/// is non-integral, negative, or >= `V`.
///
/// # Panics
/// Panics if a candle kernel fails on the validated `[N, V]` logits.
pub fn cross_entropy(logits: &DenseArray, targets: &DenseArray) -> Result<DenseArray, ArrayError> {
    let (n, v) = match logits.shape().dims() {
        [n, v] => (*n, *v),
        [b, t, v] => (b * t, *v),
        d => return Err(rank_err(d.len())),
    };
    if targets.elem_count() != n {
        return Err(ArrayError::ShapeMismatch {
            source: n,
            target: targets.elem_count(),
        });
    }
    let idx = validate_targets(targets, v)?;
    let lse = row_logsumexp(logits.data(), n, v);
    let data = logits.data();
    let total: f64 = idx
        .iter()
        .enumerate()
        .map(|(i, &ti)| lse[i] - data[i * v + ti])
        .sum();
    Ok(DenseArray::from_scalar(total / n as f64))
}

/// Build the rank error for a non-2D/3D logits tensor.
fn rank_err(got: usize) -> ArrayError {
    ArrayError::RankMismatch { expected: 2, got }
}

/// Validate targets are integral and in `[0, v)`; return `usize` indices.
fn validate_targets(targets: &DenseArray, v: usize) -> Result<Vec<usize>, ArrayError> {
    targets
        .data()
        .iter()
        .enumerate()
        .map(|(i, &t)| {
            if t < 0.0 || t.fract() != 0.0 || t as usize >= v {
                return Err(ArrayError::IndexOutOfBounds {
                    axis: 0,
                    index: i,
                    size: v,
                });
            }
            Ok(t as usize)
        })
        .collect()
}

/// Per-row log-sum-exp of `[n, v]` logits on the GPU, read back as a
/// length-`n` f64 vec for the CPU gather.
fn row_logsumexp(logits: &[f64], n: usize, v: usize) -> Vec<f64> {
    let t = dense_to_cuda(logits, &[n, v]);
    let m = t.max_keepdim(1).expect("cuda row max");
    let sumexp = t
        .broadcast_sub(&m)
        .expect("shift by row max")
        .exp()
        .expect("cuda exp")
        .sum(1)
        .expect("cuda row sum");
    let lse = (sumexp.log().expect("cuda log") + m.squeeze(1).expect("squeeze")).expect("lse add");
    cuda_to_dense_data(&lse)
}

