mod cuda_ops {
    pub use mlpl_cuda_elementwise::{add, div, exp, log, mul, neg, relu, sigmoid, sub, tanh};
    pub use mlpl_cuda_nn::{argmax, cross_entropy, log_softmax, mean, reduce_mul, softmax};
