    "mlpl-cuda-forward/cuda",
    "dep:mlpl-cuda-model",
    "mlpl-cuda-model/cuda",
    "dep:mlpl-cuda-train",
    "mlpl-cuda-train/cuda",
    "dep:candle-core",
]
# Saga 29 step 003: PNG / JPEG decode for the `load_images(dir,
# [H, W])` builtin. Off by default so the WASM target stays
# clean -- the browser REPL can still call
# `load_preloaded("pets_tiny")` because that fixture is
# pre-decoded bytes in the binary. Native binaries
# (`mlpl-cli`, `mlpl-repl`, `mlpl-serve`) enable this feature
# at build time. The decoder dispatch reads the file's magic
# bytes and routes to `png` or `jpeg-decoder` separately
# (smaller dep footprint than `image-rs`).
#
# Step 004 extends the feature to cover the `fetch_dataset`
# tarball-download path: `tar` + `flate2` for tarball extract,
# `sha2` for fixture verification, `ureq` for the HTTP GET
# itself (same pinned version + minimal-features as
# `mlpl-runtime`'s `llm_call` shim).
image-io = [
    "mlpl-eval-types/image-io",
    "dep:mlpl-eval-image",
    "mlpl-eval-image/image-io",
    "dep:png",
    "dep:jpeg-decoder",
    "dep:tar",
    "dep:flate2",
    "dep:sha2",
    "dep:ureq",
]

