use web_sys::HtmlSelectElement;
use yew::prelude::*;

use mlpl_web_demos::{DEMOS, Device, capability_for, demo_disabled};

/// One dropdown option: `(demo index, name, disabled)`.
type DemoOption = (usize, &'static str, bool);
/// Dropdown sections: `(section label, options)`.
type DemoGroups = Vec<(&'static str, Vec<DemoOption>)>;

/// Group demos for the dropdown by capability tier. `cpu`/live
/// demos keep their authored category; connect-only demos get
/// their own device-tier sections (MLX and CUDA deliberately
/// separate).
///
/// The bool is `disabled`. A connect demo is runnable only when the
/// page is `connected` AND the connected peer actually offers the
/// demo's device: a `cpu` connect demo needs only a connection (every
/// peer has cpu); an `mlx`/`cuda` demo needs the peer to report that
/// GPU in its `/v1/devices` set (`peer_devices`). This keys gating off
/// the peer's real capability rather than a static guess, so a CUDA
/// demo lights up against a CUDA peer but stays disabled against an
/// MLX-only peer (and vice versa).
fn grouped_demos(connected: bool, peer_devices: &[Device]) -> DemoGroups {
    let mut map: std::collections::BTreeMap<&str, Vec<DemoOption>> =
        std::collections::BTreeMap::new();
    for (i, d) in DEMOS.iter().enumerate() {
        let cap = capability_for(d.name);
        let section = match cap.device {
            Device::Mlx => "MLX - Apple GPU (connect)",
            Device::Cuda => "CUDA - Linux GPU (connect)",
            Device::Cpu if cap.requires_connect => "Client-server (connect)",
            Device::Cpu => d.category,
        };
        let disabled = demo_disabled(&cap, connected, peer_devices);
        map.entry(section).or_default().push((i, d.name, disabled));
    }
    for items in map.values_mut() {
        items.sort_by_key(|(_, name, _)| name.to_ascii_lowercase());
    }
    map.into_iter().collect()
}

/// The connected peer's device set for gating. Until the live
/// `GET /v1/devices` probe is consumed in the UI (the dual-backend
/// saga, where connecting to two peers at once makes the per-peer
/// truth load-bearing), assume a single connected peer offers every
/// GPU -- preserving "connect a GPU server, run its GPU demos". The
/// server-side `/v1/devices` endpoint already reports the real set.
fn peer_devices(connected: bool) -> Vec<Device> {
    if connected {
        vec![Device::Mlx, Device::Cuda]
    } else {
        Vec::new()
    }
}

