/// `GET /v1/devices` response: the compute devices this server can
/// actually run `device("...")` blocks on, in-process. The web client
/// probes this on connect to gate GPU demos by the peer's real
/// capability rather than a static guess.
#[derive(Serialize)]
pub struct DevicesResponse {
    pub devices: Vec<&'static str>,
}

/// The devices this build can dispatch: `cpu` always, plus `mlx` /
/// `cuda` when compiled with that feature on its target (the same
/// triple-gate the eval dispatch uses).
#[must_use]
pub fn compiled_devices() -> Vec<&'static str> {
    let mut devices = vec!["cpu"];
    if cfg!(all(
        feature = "mlx",
        target_os = "macos",
        target_arch = "aarch64"
    )) {
        devices.push("mlx");
    }
    if cfg!(all(
        feature = "cuda",
        target_os = "linux",
        target_arch = "x86_64"
    )) {
        devices.push("cuda");
    }
    devices
}

/// `GET /v1/devices` -- report this server's in-process device set.
pub async fn devices_handler() -> impl IntoResponse {
    Json(DevicesResponse {
        devices: compiled_devices(),
    })
}

