use web_sys::HtmlSelectElement;
use yew::prelude::*;

use mlpl_web_demos::{DEMOS, Device, capability_for, demo_disabled};

/// One dropdown option: `(demo index, name, disabled)`.
type DemoOption = (usize, &'static str, bool);
/// Dropdown sections: `(section label, options)`.
type DemoGroups = Vec<(&'static str, Vec<DemoOption>)>;

/// Group demos for the dropdown by capability tier. `cpu`/live
/// demos keep their authored category; connect-only demos get
/// their own device-tier sections (MLX and CUDA deliberately
/// separate).
///
/// The bool is `disabled`. A connect demo is runnable only when the
/// page is `connected` AND the connected peer actually offers the
/// demo's device: a `cpu` connect demo needs only a connection (every
/// peer has cpu); an `mlx`/`cuda` demo needs the peer to report that
/// GPU in its `/v1/devices` set (`peer_devices`). This keys gating off
/// the peer's real capability rather than a static guess, so a CUDA
/// demo lights up against a CUDA peer but stays disabled against an
/// MLX-only peer (and vice versa).
fn grouped_demos(connected: bool, peer_devices: &[Device]) -> DemoGroups {
    let mut map: std::collections::BTreeMap<&str, Vec<DemoOption>> =
        std::collections::BTreeMap::new();
    for (i, d) in DEMOS.iter().enumerate() {
        let cap = capability_for(d.name);
        let section = match cap.device {
            Device::Mlx => "MLX - Apple GPU (connect)",
            Device::Cuda => "CUDA - Linux GPU (connect)",
            Device::Cpu if cap.requires_connect => "Client-server (connect)",
            Device::Cpu => d.category,
        };
        let disabled = demo_disabled(&cap, connected, peer_devices);
        map.entry(section).or_default().push((i, d.name, disabled));
    }
    for items in map.values_mut() {
        items.sort_by_key(|(_, name, _)| name.to_ascii_lowercase());
    }
    map.into_iter().collect()
}

/// Map `GET /v1/devices` name strings to [`Device`]s for gating.
/// Unknown names are dropped.
fn devices_from_names(names: &[String]) -> Vec<Device> {
    names
        .iter()
        .filter_map(|n| match n.as_str() {
            "cpu" => Some(Device::Cpu),
            "mlx" => Some(Device::Mlx),
            "cuda" => Some(Device::Cuda),
            _ => None,
        })
        .collect()
}

#[derive(Properties, PartialEq)]
pub struct ModeBarProps {
    pub on_demo: Callback<usize>,
    pub on_upload: Callback<web_sys::Event>,
    /// Saga 29 step 016: cancel handler for the `<input
    /// type=file>`'s `cancel` event. Binds `Err("cancelled")`
    /// under the pending upload name when the user dismisses
    /// the file picker.
    pub on_upload_cancel: Callback<web_sys::Event>,
    /// Saga 29 step 016: lifted to the parent so the
    /// `:upload <name>` REPL command handler in handlers.rs
    /// can also click() the input programmatically.
    pub upload_input_ref: NodeRef,
    pub tutorial_active: bool,
}

#[function_component(ModeBar)]
pub fn mode_bar(props: &ModeBarProps) -> Html {
    let cls = if props.tutorial_active {
        "modebar tutorial"
    } else {
        "modebar repl"
    };
    // Probe the connected peer's real device set once on mount, so the
    // dropdown gates GPU demos by what THIS peer offers (CUDA on a
    // Linux peer, MLX on an Apple peer) -- not a static guess.
    let peer_devices = use_state(Vec::<Device>::new);
    {
        let peer_devices = peer_devices.clone();
        use_effect_with((), move |()| {
            if let Some(url) = mlpl_web_eval::eval_url::current_connect_url() {
                yew::platform::spawn_local(async move {
                    let names = mlpl_web_eval::devices::fetch_devices(&url).await;
                    peer_devices.set(devices_from_names(&names));
                });
            }
            || ()
        });
    }
    let demo_dropdown =
        render_demo_dropdown(props.tutorial_active, props.on_demo.clone(), &peer_devices);
    let upload_widget = render_upload_widget(props);
    html! {
        <div class={cls}>
            { demo_dropdown }
            { upload_widget }
        </div>
    }
}

